class RangeArray {
    private final long[] a;

    RangeArray(int[] input) {
        a = new long[input.length];
        for (int i = 0; i < input.length; i++) {
            a[i] = input[i];
        }
    }

    void update(int i, int val) {
        a[i] = val;            // O(1)
    }

    long rangeSum(int l, int r) {
        long sum = 0;
        for (int i = l; i <= r; i++) {  // O(n)
            sum += a[i];
        }
        return sum;
    }
}

