class SegmentTree {
    private final long[] tree;
    private final int n;

    SegmentTree(int[] a) {
        n = a.length;
        tree = new long[4 * n];   // safe upper bound
        if (n > 0) build(a, 1, 0, n - 1);
    }

    private void build(int[] a, int node, int lo, int hi) {
        if (lo == hi) {
            tree[node] = a[lo];
            return;
        }
        int mid = (lo + hi) >>> 1;
        build(a, 2 * node, lo, mid);
        build(a, 2 * node + 1, mid + 1, hi);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    void update(int i, int val) {
        update(1, 0, n - 1, i, val);
    }

    private void update(int node, int lo, int hi, int i, int val) {
        if (lo == hi) {
            tree[node] = val;
            return;
        }
        int mid = (lo + hi) >>> 1;
        if (i <= mid) {
            update(2 * node, lo, mid, i, val);
        } else {
            update(2 * node + 1, mid + 1, hi, i, val);
        }
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    long rangeSum(int l, int r) {
        return query(1, 0, n - 1, l, r);
    }

    private long query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) {
            return 0;                 // fully outside: additive identity
        }
        if (l <= lo && hi <= r) {
            return tree[node];        // fully inside: stored sum
        }
        int mid = (lo + hi) >>> 1;
        return query(2 * node, lo, mid, l, r)
             + query(2 * node + 1, mid + 1, hi, l, r);
    }

    public static void main(String[] args) {
        SegmentTree st = new SegmentTree(new int[]{1, 3, 5, 7, 9, 11});
        System.out.println(st.rangeSum(1, 3)); // 15
        st.update(1, 10);
        System.out.println(st.rangeSum(1, 3)); // 22
        System.out.println(st.rangeSum(0, 5)); // 43
    }
}

