class SegmentTree:
    def __init__(self, a: list[int]) -> None:
        self.n = len(a)
        self.tree = [0] * (4 * self.n)
        if self.n > 0:
            self._build(a, 1, 0, self.n - 1)

    def _build(self, a: list[int], node: int, lo: int, hi: int) -> None:
        if lo == hi:
            self.tree[node] = a[lo]
            return
        mid = (lo + hi) // 2
        self._build(a, 2 * node, lo, mid)
        self._build(a, 2 * node + 1, mid + 1, hi)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def update(self, i: int, val: int) -> None:
        self._update(1, 0, self.n - 1, i, val)

    def _update(self, node: int, lo: int, hi: int, i: int, val: int) -> None:
        if lo == hi:
            self.tree[node] = val
            return
        mid = (lo + hi) // 2
        if i <= mid:
            self._update(2 * node, lo, mid, i, val)
        else:
            self._update(2 * node + 1, mid + 1, hi, i, val)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def range_sum(self, l: int, r: int) -> int:
        return self._query(1, 0, self.n - 1, l, r)

    def _query(self, node: int, lo: int, hi: int, l: int, r: int) -> int:
        if r < lo or hi < l:
            return 0                  # fully outside: additive identity
        if l <= lo and hi <= r:
            return self.tree[node]    # fully inside: stored sum
        mid = (lo + hi) // 2
        return (self._query(2 * node, lo, mid, l, r)
                + self._query(2 * node + 1, mid + 1, hi, l, r))


